import * as s from "../core/validation/index.js";
import type { JsonValue, Schema } from "../core/validation/schema.js";
import {
  storyCitationResolvingTypeSchema,
  type StoryCitationResolvingType,
} from "./story-citation-resolving-type.js";

/** Citation settings for newsletters generated by the monitor. */
export type SignalMonitoringPlanNewsletterConfig = {
  /** Whether generated newsletters include citations. Defaults to true. */
  citations?: boolean | null;
  /** How story citations are resolved. Accepts STORY or TOP_ARTICLE. */
  storyCitationResolvingType: StoryCitationResolvingType;
  /** Properties the service sent or accepts beyond those declared. */
  additionalProperties?: Record<string, JsonValue>;
};

export const signalMonitoringPlanNewsletterConfigSchema: Schema<SignalMonitoringPlanNewsletterConfig> =
  s.object<SignalMonitoringPlanNewsletterConfig>(
    {
      citations: s.optionalNullable(s.boolean()),
      storyCitationResolvingType: storyCitationResolvingTypeSchema,
    },
    { additionalProperties: s.json() },
  );
